import subprocess,json,base64,shutil
out={'schema':'VST_S2_4D_GUARD_DBUS_DIAGNOSTIC_V1','mode':'read-only busctl version and typed systemd Conditions for exact two units','busctl_path':shutil.which('busctl'),'commands':[]}
commands=[('version',['/usr/bin/busctl','--version'])]
for unit in ['vst-runner.service','vst-dispatcher.service']:
 obj='/org/freedesktop/systemd1/unit/'+unit.replace('_','_5f').replace('.','_2e').replace('-','_2d')
 commands.append((unit,['/usr/bin/busctl','--system','--json=short','get-property','org.freedesktop.systemd1',obj,'org.freedesktop.systemd1.Unit','Conditions']))
for name,args in commands:
 try:
  p=subprocess.run(args,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False,timeout=15,env={'LC_ALL':'C','PATH':'/usr/bin:/bin'})
  out['commands'].append({'name':name,'argv':args,'returncode':p.returncode,'stdout_b64':base64.b64encode(p.stdout).decode(),'stderr_b64':base64.b64encode(p.stderr).decode(),'stdout_utf8':p.stdout.decode('utf8','backslashreplace'),'stderr_utf8':p.stderr.decode('utf8','backslashreplace')})
 except Exception as e:out['commands'].append({'name':name,'argv':args,'exception':type(e).__name__+': '+str(e)})
print(json.dumps(out,sort_keys=True,separators=(',',':')))
